"""Driver for the Brevalt KX-100 RF power meter. The programming manual is MANUAL.md.

`session` is an open connection to the meter with three methods:
    session.write(cmd: str) -> None
    session.read() -> str
    session.query(cmd: str) -> str      # write, then read
"""

# Longest run of SYST:ERR? reads: the queue holds 10 errors, plus the final 0,"No error".
_ERROR_QUEUE_SIZE = 10
# Bound on *OPC? polls; the meter answers "1" when the measurement is complete.
_OPC_POLL_LIMIT = 1000


class InstrumentError(Exception):
    """The meter reported an error: SYST:ERR? returned a code other than 0."""


def _parse_error(response: str) -> tuple[int, str]:
    """Split a SYST:ERR? response `code,"text"` into (code, text)."""
    code_str, _, text = response.strip().partition(",")
    try:
        code = int(code_str)
    except ValueError as e:
        raise InstrumentError(f"unparseable SYST:ERR? response: {response!r}") from e
    return code, text.strip().strip('"')


def _drain_errors(session) -> list[tuple[int, str]]:
    """Read the error queue until it is empty; return the errors found, oldest first."""
    errors: list[tuple[int, str]] = []
    for _ in range(_ERROR_QUEUE_SIZE + 1):
        code, text = _parse_error(session.query("SYST:ERR?"))
        if code == 0:
            return errors
        errors.append((code, text))
    # The queue cannot hold more than this; something is wrong with the session.
    raise InstrumentError(f"error queue did not empty: {errors}")


def _format_frequency(freq_hz: float) -> str:
    return repr(float(freq_hz))


def _format_count(averages: int) -> str:
    # Send integral values as plain integers; anything else is passed through so the meter
    # refuses it (-104) rather than silently truncating it here.
    if isinstance(averages, bool):
        return str(int(averages))
    if isinstance(averages, int):
        return str(averages)
    value = float(averages)
    return str(int(value)) if value.is_integer() else repr(value)


def measure_power(session, freq_hz: float, averages: int) -> float:
    """Measure the power of a signal at `freq_hz`, averaging `averages` readings, and return it in dBm.

    Raise InstrumentError if the meter reports any error while configuring or measuring.
    """
    # Section 3, "Required measurement sequence".
    session.write("*CLS")
    session.write(f"SENS:FREQ {_format_frequency(freq_hz)}")
    session.write(f"SENS:AVER:COUN {_format_count(averages)}")
    session.write("CONF:POW:RANG AUTO")
    session.write("INIT")

    for _ in range(_OPC_POLL_LIMIT):
        if session.query("*OPC?").strip() == "1":
            break
    else:
        raise InstrumentError("measurement did not complete (*OPC? never returned 1)")

    reading = session.query("FETC?").strip()

    # Any queued error means a setting was refused or the reading is not valid.
    errors = _drain_errors(session)
    if errors:
        detail = "; ".join(f'{code},"{text}"' for code, text in errors)
        raise InstrumentError(f"meter reported error(s): {detail}")

    try:
        value = float(reading)
    except ValueError as e:
        raise InstrumentError(f"unparseable FETC? response: {reading!r}") from e
    if value >= 9.9e37:
        # Over-range sentinel; normally accompanied by error 201, but never a valid reading.
        raise InstrumentError(f"measurement over range (FETC? returned {reading})")
    return value

